function evenOutCost(basket1: number[], basket2: number[]): number {
  const total = new Map<number, number>();
  for (const x of [...basket1, ...basket2]) total.set(x, (total.get(x) ?? 0) + 1);
  for (const c of total.values()) if (c % 2) return -1;
  const half: number[] = [];
  for (const [v, c] of total) for (let i = 0; i < c / 2; i++) half.push(v);
  const goal = half.sort((a, b) => a - b).join(",");
  const rest = (b1: number[]): number[] => {
    const left = new Map(total);
    for (const x of b1) left.set(x, left.get(x)! - 1);
    const out: number[] = [];
    for (const [v, c] of left) for (let i = 0; i < c; i++) out.push(v);
    return out;
  };
  const dist = new Map<string, number>([[[...basket1].sort((a, b) => a - b).join(","), 0]]);
  const done = new Set<string>();
  for (;;) {
    let key = "", cost = Infinity;
    for (const [k, d] of dist) if (!done.has(k) && d < cost) { cost = d; key = k; }
    if (key === goal) return cost;
    done.add(key);
    const b1 = key.split(",").map(Number);
    for (const y of new Set(rest(b1))) {
      for (let i = 0; i < b1.length; i++) {
        if (b1[i] === y) continue;
        const nb = [...b1];
        nb[i] = y;
        const k = nb.sort((a, b) => a - b).join(",");
        const nd = cost + Math.min(b1[i], y);
        if (nd < (dist.get(k) ?? Infinity)) dist.set(k, nd);
      }
    }
  }
}

