class Solution:
    def evenOutCost(self, basket1: List[int], basket2: List[int]) -> int:
        total = Counter(basket1) + Counter(basket2)
        if any(c % 2 for c in total.values()):
            return -1
        goal = tuple(sorted(v for v, c in total.items() for _ in range(c // 2)))
        start = tuple(sorted(basket1))
        dist = {start: 0}
        heap = [(0, start)]
        while heap:
            cost, b1 = heapq.heappop(heap)
            if b1 == goal:
                return cost
            if cost > dist[b1]:
                continue
            rest = total - Counter(b1)
            for y in rest:
                for i, x in enumerate(b1):
                    if x == y:
                        continue
                    nb = tuple(sorted(b1[:i] + (y,) + b1[i + 1:]))
                    nd = cost + min(x, y)
                    if nd < dist.get(nb, float("inf")):
                        dist[nb] = nd
                        heapq.heappush(heap, (nd, nb))
        return -1

