function evenOutCost(basket1: number[], basket2: number[]): number {
  const diff = new Map<number, number>();
  let low = Infinity;
  for (const x of basket1) { diff.set(x, (diff.get(x) ?? 0) + 1); low = Math.min(low, x); }
  for (const x of basket2) { diff.set(x, (diff.get(x) ?? 0) - 1); low = Math.min(low, x); }
  const moves: number[] = [];
  for (const [price, d] of diff) {
    if (d % 2 !== 0) return -1;
    for (let i = 0; i < Math.abs(d) / 2; i++) moves.push(price);
  }
  moves.sort((a, b) => a - b);
  let cost = 0;
  for (let i = 0; i < moves.length / 2; i++) cost += Math.min(moves[i], 2 * low);
  return cost;
}

