class Solution:
    def evenOutCost(self, basket1: List[int], basket2: List[int]) -> int:
        diff = Counter(basket1)
        diff.subtract(basket2)
        low = min(min(basket1), min(basket2))
        moves = []
        for price, d in diff.items():
            if d % 2:
                return -1
            moves.extend([price] * (abs(d) // 2))
        moves.sort()
        return sum(min(x, 2 * low) for x in moves[: len(moves) // 2])

